const updateSmtp = `-- name: UpdateSmtp :one
UPDATE smtp_configs
SET revision = revision + 1, enabled = $2, host = $3, port = $4, tls_mode = $5, username = $6, from_address = $7,
    key_id = $8, nonce = $9, ciphertext = $10, updated_at = now()
WHERE id = $1
RETURNING id, owner_kind, user_id, revision, enabled, host, port, tls_mode, username, from_address, key_id, nonce, ciphertext, updated_at
`

type UpdateSmtpParams struct {
	ID          uuid.UUID `json:"id"`
	Enabled     bool      `json:"enabled"`
	Host        string    `json:"host"`
	Port        int32     `json:"port"`
	TlsMode     string    `json:"tls_mode"`
	Username    string    `json:"username"`
	FromAddress string    `json:"from_address"`
	KeyID       *string   `json:"key_id"`
	Nonce       []byte    `json:"nonce"`
	Ciphertext  []byte    `json:"ciphertext"`
}

func (q *Queries) UpdateSmtp(ctx context.Context, arg UpdateSmtpParams) (SmtpConfig, error) {
	row := q.db.QueryRow(ctx, updateSmtp,
		arg.ID,
		arg.Enabled,
		arg.Host,
		arg.Port,
		arg.TlsMode,
		arg.Username,
		arg.FromAddress,
		arg.KeyID,
		arg.Nonce,
		arg.Ciphertext,
	)
	var i SmtpConfig
	err := row.Scan(
		&i.ID,
		&i.OwnerKind,
		&i.UserID,
		&i.Revision,
		&i.Enabled,
		&i.Host,
		&i.Port,
		&i.TlsMode,
		&i.Username,
		&i.FromAddress,
		&i.KeyID,
		&i.Nonce,
		&i.Ciphertext,
		&i.UpdatedAt,
	)
	return i, err
}
